// Edite somente o mercado-alvo. O vínculo com o diagnóstico é estável e versionado.
const city = 'São Paulo/SP';
const targetVertical = 'distribuidora';
return [{ json: {
  city,
  targetVertical,
  query: `${targetVertical} em ${city}`,
  minimumReviewCount: 30,
  minimumRating: 4,
  reviewThreshold: 45,
  diagnosticFormUrl: 'https://docs.google.com/forms/d/e/1FAIpQLScknF_YOBUHrX94tfgykv37NaEryAzqzIdc55Hel8RX1wp2Sg/viewform',
  diagnosticCompanyEntryId: '171063854',
} }];

const cfg = $('Config — mercado-alvo').first().json;
const places = $json.places ?? [];
const discoveredAt = new Date().toISOString();

return places.map((place) => {
  const companyName = place.displayName?.text ?? '';
  const address = place.formattedAddress ?? '';
  const placeId = place.id ?? '';
  const companyId = (placeId || `${companyName}|${address}`).toLowerCase();
  return {
    json: {
      dedupe_key: companyId,
      company_id: companyId,
      place_id: placeId,
      company_name: companyName,
      address,
      website: place.websiteUri ?? '',
      phone: place.nationalPhoneNumber ?? '',
      types: (place.types ?? []).join(', '),
      rating: Number(place.rating ?? 0),
      review_count: Number(place.userRatingCount ?? 0),
      business_status: place.businessStatus ?? 'UNKNOWN',
      discovered_at: discoveredAt,
      search_query: cfg.query,
      city: cfg.city,
      target_vertical: cfg.targetVertical,
    },
  };
});

const cfg = $('Config — mercado-alvo').first().json;

return $input.all().map(({ json: lead }) => {
  let fit = 0;
  let complexity = 0;
  let reachability = 0;
  const reasons = [];

  // Public signals only: priority for human research, never a diagnosis.
  if (lead.business_status === 'OPERATIONAL') { fit += 10; reasons.push('status operacional público'); }
  if (lead.rating >= cfg.minimumRating) { fit += 10; reasons.push(`nota pública ${lead.rating}`); }
  if (lead.review_count >= cfg.minimumReviewCount) { fit += 20; reasons.push(`${lead.review_count} avaliações públicas`); }
  else if (lead.review_count >= 10) { fit += 8; reasons.push(`${lead.review_count} avaliações públicas`); }
  if (lead.website) { reachability += 10; reasons.push('site institucional público'); }
  if (lead.phone) { reachability += 5; reasons.push('telefone institucional público'); }
  if (lead.address) { fit += 5; reasons.push('endereço comercial público'); }
  if (lead.types.includes('store') || lead.types.includes('point_of_interest')) { complexity += 5; }

  const leadScore = Math.min(100, fit + complexity + reachability);
  const status = leadScore >= cfg.reviewThreshold ? 'REVIEW' : 'DESCARTAR';
  const researchNote = status === 'REVIEW'
    ? 'Validar manualmente segmento, porte, decisor e hipótese antes de qualquer contato.'
    : 'Não priorizado nesta rodada; score é apenas triagem por sinais públicos.';

  return { json: {
    ...lead,
    fit_score: fit,
    complexity_score: complexity,
    reachability_score: reachability,
    lead_score: leadScore,
    score_reason: reasons.join('; '),
    status,
    research_note: researchNote,
  }};
});

const cfg = $('Config — mercado-alvo').first().json;
const error = $json.error ?? {};
const cause = error.message ?? error.description ?? $json.message ?? 'Falha sem detalhe retornado pelo Google Places';
const occurredAt = new Date().toISOString();
const companyId = `google-places-error-${Date.now()}`;
return [{ json: {
  dedupe_key: companyId,
  company_id: companyId,
  place_id: '',
  company_name: '[FALHA] Google Places',
  address: '', website: '', phone: '', types: '', rating: '', review_count: '', business_status: '',
  discovered_at: occurredAt,
  fit_score: '', complexity_score: '', reachability_score: '', lead_score: '', score_reason: '',
  status: 'ERROR',
  research_note: `Consulta: ${cfg.query}. Após 3 tentativas, Google Places falhou. Causa: ${String(cause).slice(0, 800)}`,
} }];

const FORM_URL = 'https://docs.google.com/forms/d/e/1FAIpQLScknF_YOBUHrX94tfgykv37NaEryAzqzIdc55Hel8RX1wp2Sg/viewform';
const COMPANY_ENTRY_ID = '171063854';
const now = new Date().toISOString();

return $input.all().flatMap(({ json: lead }) => {
  const status = String(lead.status ?? '').trim().toUpperCase();
  const diagnosticStatus = String(lead.diagnostic_status ?? '').trim().toUpperCase();
  if (status !== 'CONTACT_ACCEPTED' || ['INVITE_READY', 'INVITED', 'IN_PROGRESS', 'REVIEW_REQUIRED', 'COMPLETED'].includes(diagnosticStatus)) return [];

  const companyId = String(lead.company_id || lead.dedupe_key || '').trim();
  const companyName = String(lead.company_name || '').trim();
  if (!companyId || !companyName) return [];

  const companyRef = `${companyId}::${companyName}`;
  const formUrl = `${FORM_URL}?usp=pp_url&entry.${COMPANY_ENTRY_ID}=${encodeURIComponent(companyRef)}`;
  const message = `Olá! Conforme combinado, este é o diagnóstico operacional PRUMO de ${companyName}. Cada uma das cinco perspectivas deve responder uma vez: ${formUrl}`;
  const channel = String(lead.contact_channel ?? '').trim().toLowerCase();
  const destination = String(lead.contact_url ?? '').trim();
  let actionUrl = formUrl;
  if (channel.includes('whatsapp')) {
    const digits = destination.replace(/\D/g, '');
    if (digits) actionUrl = `https://wa.me/${digits}?text=${encodeURIComponent(message)}`;
  } else if (channel.includes('email') || destination.includes('@')) {
    const email = destination.replace(/^mailto:/i, '');
    actionUrl = `mailto:${email}?subject=${encodeURIComponent(`Diagnóstico PRUMO — ${companyName}`)}&body=${encodeURIComponent(message)}`;
  }

  return [{ json: {
    company_id: companyId,
    dedupe_key: String(lead.dedupe_key || companyId),
    status: 'DIAGNOSTIC_INVITE_READY',
    diagnostic_status: 'INVITE_READY',
    diagnostic_form_url: formUrl,
    diagnostic_invite_message: message,
    diagnostic_invite_action_url: actionUrl,
    diagnostic_next_action: 'Enviar o convite pelo canal validado e, após o envio, marcar diagnostic_status como INVITED.',
    diagnostic_updated_at: now,
  } }];
});
